                        [
                            'title' => 'Tone, Register, and Connotation',
                            'objective' => 'Detect irony, skepticism, and loaded word choices in sophisticated prose.',
                            'xp' => 30, 'minutes' => 15,
                            'prerequisites' => ['Argument Structure and Logical Fallacies'],
                            'sections' => [
                                ['type' => 'intro', 'title' => 'Reading the music, not just the words', 'body' => 'Two reviews can contain identical facts and opposite verdicts. The difference lives in tone — word choice, irony, what is praised faintly and what is conspicuously omitted. "The hotel is adequate" is factually positive and rhetorically damning.'],
                                ['type' => 'explanation', 'title' => 'Tools for reading tone', 'body' => "Connotation: near-synonyms carry different charges — resolute (+) vs stubborn (−) vs inflexible (−−); thrifty (+) vs cheap (−).\n\nFaint praise: \"adequate\", \"serviceable\", \"competent\" often signal disappointment in reviews.\n\nIrony and scare quotes: The company's \"world-class\" support left me on hold for three hours — the quotes reverse the meaning.\n\nDistancing verbs: \"claims\", \"insists\", \"purports\" signal the writer doubts what is reported: \"The vendor claims the fix is complete.\"", 'body_id' => 'Konotasi: sinonim dekat membawa muatan berbeda (resolute positif, stubborn negatif). Pujian hambar ("adequate") sering berarti kekecewaan. Tanda kutip ironis membalik makna, dan kata seperti "claims" menandakan penulis meragukan pernyataan itu.'],
                                ['type' => 'examples', 'title' => 'Examples', 'meta' => ['items' => [
                                    ['en' => 'The minister insists the figures are accurate.', 'id' => '"Insists" mengisyaratkan penulis meragukan angka-angka itu.'],
                                    ['en' => 'The food was edible, and the service existed.', 'id' => 'Pujian hambar yang sebenarnya merupakan kritik pedas.'],
                                    ['en' => 'Their "innovative" strategy is a copy of last year\'s.', 'id' => 'Tanda kutip membuat "innovative" menjadi sindiran.'],
                                ]]],
                                ['type' => 'vocabulary', 'title' => 'Connotation pairs', 'meta' => ['words' => [
                                    ['word' => 'resolute', 'ipa' => '/ˈrez.ə.luːt/', 'meaning_id' => 'teguh (konotasi positif)', 'example' => 'She remained resolute under pressure.'],
                                    ['word' => 'stubborn', 'ipa' => '/ˈstʌb.ɚn/', 'meaning_id' => 'keras kepala (konotasi negatif)', 'example' => 'He was too stubborn to accept feedback.'],
                                    ['word' => 'purport', 'ipa' => '/pɚˈpɔːrt/', 'meaning_id' => 'mengaku-aku; konon', 'example' => 'The memo purports to summarize the meeting.'],
                                ]]],
                                ['type' => 'tip', 'title' => 'Tip', 'body' => 'Ask of any evaluative text: which words could be swapped for a neutral synonym? Each non-neutral choice is a deliberate signal of the writer\'s stance.'],
                            ],
                            'exercises' => [[
                                'title' => 'Practice: Tone and Connotation',
                                'xp' => 15, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'multiple_choice', 'prompt' => 'Which sentence conveys doubt about the CEO\'s statement?', 'difficulty' => 'hard',
                                        'options' => [['The CEO claims the layoffs are finished.', true], ['The CEO announced that the layoffs are finished.', false], ['The CEO confirmed the layoffs are finished.', false]]],
                                    ['type' => 'multiple_choice', 'prompt' => 'In a restaurant review, "the soup was adequate" most likely expresses ___.', 'difficulty' => 'medium',
                                        'options' => [['polite disappointment', true], ['strong enthusiasm', false], ['neutral description with no opinion', false]]],
                                    ['type' => 'multiple_choice', 'prompt' => 'Which word describes a careful spender with a POSITIVE connotation?', 'difficulty' => 'medium',
                                        'options' => [['thrifty', true], ['stingy', false], ['cheap', false], ['miserly', false]]],
                                    ['type' => 'true_false', 'prompt' => 'Scare quotes around a word, as in their "premium" service, usually intensify praise.', 'config' => ['correct' => false],
                                        'explanation' => 'Scare quotes signal irony or doubt — they undercut the word.'],
                                    ['type' => 'matching', 'prompt' => 'Match each neutral idea to the negatively loaded word.', 'config' => ['pairs' => [
                                        ['left' => 'determined (neutral)', 'right' => 'stubborn'], ['left' => 'careful with money (neutral)', 'right' => 'stingy'], ['left' => 'said (neutral)', 'right' => 'insisted']]]],
                                    ['type' => 'reading', 'prompt' => 'What is the reviewer\'s overall verdict on the laptop?', 'passage' => 'The laptop\'s design is unquestionably striking, and the keyboard is a genuine pleasure. The battery, however, "lasts all day" only if your day ends at lunch, and the much-advertised cooling system whines like a hair dryer. Buyers seduced by the aluminum shell may find the honeymoon brief.',
                                        'options' => [['Attractive but seriously flawed — the praise is outweighed by ironic criticism.', true], ['An unreserved recommendation.', false], ['Entirely negative with no praise at all.', false]]],
                                ],
